'use strict';
const DATA=window.QUIZ_DATA, KEY='recall-progress-v1', $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={'listening-t2':'听力 Task 2','listening-t3':'听力 Task 3','listening-t4':'听力 Task 4','reading-t3':'阅读 Task 3','speaking-t1':'口语 Task 1'};
let state={records:{},stars:[],current:null}, queue=[], current, translated=false, subject='all', hideEnglish=false;
try {const saved=JSON.parse(localStorage.getItem(KEY));if(saved&&saved.records&&Array.isArray(saved.stars))state=saved;}catch{}
function notify(msg){$('#toast').textContent=msg;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2800)}
function save(){state.current=current?.id;state.filters={subject,category:$('#category').value};try{localStorage.setItem(KEY,JSON.stringify(state))}catch{notify('当前浏览器无法保存，请导出进度备份。')}stats()}
function updateTasks(){const cats=Object.keys(names).filter(k=>subject==='all'||k.startsWith(subject));$('#category').innerHTML='<option value="all">全部 Task</option>'+cats.map(k=>`<option value="${k}">${names[k]} · ${DATA.filter(a=>a.category===k).length} 篇</option>`).join('');document.querySelectorAll('[data-subject]').forEach(b=>{b.classList.toggle('active',b.dataset.subject===subject);b.setAttribute('aria-pressed',String(b.dataset.subject===subject))})}
function stats(){const done=DATA.filter(a=>state.records[a.id]?.submitted),rs=done.filter(a=>a.category!=='speaking-t1').map(a=>state.records[a.id]),total=rs.reduce((n,r)=>n+Object.keys(r.answers).length,0),right=rs.reduce((n,r)=>n+r.correct,0);$('#stats').textContent=`${DATA.length} 篇 · 已完成 ${done.length} 篇 · 选择题正确率 ${total?Math.round(right/total*100):0}% · 口语已复习 ${done.filter(a=>a.category==='speaking-t1').length} 篇`}
function record(){return state.records[current.id]||{answers:{},submitted:false}}
function rebuild(preserve=true){const cat=$('#category').value,mode=$('#mode').value,s=$('#search').value.trim().toLowerCase();queue=DATA.filter(a=>{const r=state.records[a.id];return(subject==='all'||a.category.startsWith(subject))&&(cat==='all'||cat===a.category)&&(!s||(a.title+a.titleZh).toLowerCase().includes(s))&&(mode==='all'||mode==='new'&&!r?.submitted||mode==='wrong'&&r?.submitted&&r.correct<a.questions.length||mode==='star'&&state.stars.includes(a.id))}).sort((a,b)=>(b.frequency||0)-(a.frequency||0));current=(preserve&&queue.find(a=>a.id===(current?.id||state.current)))||queue[0];render()}
function menu(){const selected=current?.id;$('#count').textContent=`当前范围 ${queue.length} 篇`;$('#list').innerHTML=queue.map((a,i)=>`<button class="article-link ${a.id===selected?'active':''}" data-id="${esc(a.id)}">${String(i+1).padStart(2,'0')}　${esc(a.titleZh)}<small>${esc(names[a.category])} · ${a.frequency||'—'} 次 ${state.records[a.id]?.submitted?'· 已完成':''}</small></button>`).join('');$('#list').querySelectorAll('button').forEach(b=>b.onclick=()=>{current=queue.find(a=>a.id===b.dataset.id);render();save()})}
function render(){menu();stats();if(!current){$('#article').innerHTML='<div class="empty"><h2>这个范围已刷完</h2><p>切换练习范围，或选一个新的题库。</p></div>';return}const a=current,r=record(),pos=queue.indexOf(a),speaking=a.category==='speaking-t1';$('#article').innerHTML=`<div class="meta"><span class="badge">${esc(names[a.category])}</span><span>第 ${pos+1} / ${queue.length} 篇</span><span>出现 ${a.frequency||'—'} 次</span><span>${a.questions.length} ${speaking?'句复述':'道题'}</span></div><h2>${esc(a.title)}</h2><p class="subtitle">${esc(a.titleZh)}</p><div class="top-actions">${speaking?'<a class="study-link" href="memorize.html">背诵总览 · 全部30篇 ↗</a>':''}<label class="toggle"><input type="checkbox" id="translation" ${translated?'checked':''}>显示中文译文</label>${speaking?`<button id="hide-english">${hideEnglish?'显示英文原句':'遮住英文自测'}</button>`:''}<button id="star">${state.stars.includes(a.id)?'★ 已收藏':'☆ 收藏文章'}</button></div><div class="columns"><div class="card passage-card"><div class="section-label">01 / READ THE PASSAGE</div>${speaking?`<p class="muted">先读7句原文，再遮住英文，根据右侧中文提示复述，逐句自评。</p><p class="muted">${esc(a.tips)}</p>`:''}<div class="passage">${a.passage.map(([en,zh])=>`<p class="english ${speaking&&hideEnglish?'hidden':''}">${esc(en)}</p><p class="zh ${translated?'':'hidden'}">${esc(zh)}</p>`).join('')}${a.supplement.length?'<h3>补充原文（对应版本差异）</h3>'+a.supplement.map(([en,zh])=>`<p class="english ${speaking&&hideEnglish?'hidden':''}">${esc(en)}</p><p class="zh ${translated?'':'hidden'}">${esc(zh)}</p>`).join(''):''}</div><details><summary>出现日期与来源</summary>${esc(a.dates.join(' · '))}<br>来源：考拉机经与已整理的复习资料。阅读原题库标为 Task 3。</details></div><div><div class="card"><div class="section-label">02 / CHECK YOUR RECALL</div>${a.questions.map((q,i)=>`<section class="question"><div class="prompt">${i+1}. ${esc(q.prompt)}</div>${q.choices.map(c=>`<button class="choice ${r.answers[q.id]===c.id?'selected':''} ${r.submitted&&c.id===q.answer?'correct':''} ${r.submitted&&r.answers[q.id]===c.id&&c.id!==q.answer?'incorrect':''}" data-q="${q.id}" data-c="${esc(c.id)}" aria-pressed="${r.answers[q.id]===c.id}" ${r.submitted?'disabled':''}><span class="letter">${esc(c.id)}</span><span>${esc(c.text)}</span></button>`).join('')}${r.submitted?`<div class="result"><strong>${speaking?(r.answers[q.id]==='A'?'自评：能完整复述':'自评：还需复习'):(r.answers[q.id]===q.answer?'✓ 回忆正确':'✗ 回忆有误')}${speaking?'':' · 正确答案 '+esc(q.answer)}</strong><p>${esc(q.promptZh)}：${esc(q.explanationZh)}</p><p>${esc(q.explanation)}</p>${q.evidence.length?'<blockquote>'+esc(q.evidence.join(' '))+'</blockquote>':''}</div>`:''}</section>`).join('')}</div><div id="feedback" role="status">${r.submitted?`${speaking?'自评能复述':'本篇答对'} ${r.correct} / ${a.questions.length} ${speaking?'句（自评记录，不是口语评分）':'题 · '+Math.round(r.correct/a.questions.length*100)+'%'}<br>${esc(a.summary)}`:`已选择 ${Object.keys(r.answers).length} / ${a.questions.length} ${speaking?'句，提交后对照原句；按实际复述情况自评。':'题，提交后显示答案。'}`}</div><div class="bottom-actions"><button id="submit" class="primary" ${r.submitted?'disabled':''}>${speaking?'保存本篇自评':'提交本篇'}</button><button id="retry">重新做本篇</button><button id="prev" ${pos===0?'disabled':''}>上一篇</button><button id="next">${pos===queue.length-1?'完成本轮':'下一篇 →'}</button></div></div></div>`;
if(speaking)$('#hide-english').onclick=()=>{hideEnglish=!hideEnglish;render()};$('#translation').onchange=e=>{translated=e.target.checked;document.querySelectorAll('.zh').forEach(n=>n.classList.toggle('hidden',!translated))};$('#star').onclick=()=>{state.stars=state.stars.includes(a.id)?state.stars.filter(id=>id!==a.id):[...state.stars,a.id];save();render()};document.querySelectorAll('.choice').forEach(b=>b.onclick=()=>{const rr=record();rr.answers[b.dataset.q]=b.dataset.c;state.records[a.id]=rr;save();const scroll=window.scrollY;render();window.scrollTo(0,scroll)});
$('#submit').onclick=()=>{const rr=record();if(a.questions.some(q=>!rr.answers[q.id])){notify('请先完成本篇所有题目，再提交。');return}rr.submitted=true;rr.correct=a.questions.filter(q=>rr.answers[q.id]===q.answer).length;rr.updatedAt=new Date().toISOString();state.records[a.id]=rr;save();render()};$('#retry').onclick=()=>{state.records[a.id]={answers:{},submitted:false};save();render()};$('#prev').onclick=()=>move(-1);$('#next').onclick=()=>move(1)}
function move(n){const i=queue.indexOf(current)+n;if(i>=queue.length){$('#article').innerHTML=`<div class="empty"><h2>这一轮完成了。</h2><p>你已浏览本轮 ${queue.length} 篇文章。可切换「错题文章」继续巩固。</p><button id="again" class="primary">返回本轮第一篇</button></div>`;$('#again').onclick=()=>{current=queue[0];render()};return}if(i<0)return;current=queue[i];save();render();$('#workspace').scrollIntoView({behavior:'smooth',block:'start'})}
document.querySelectorAll('[data-subject]').forEach(b=>b.onclick=()=>{subject=b.dataset.subject;$('#search').value='';$('#mode').value='all';updateTasks();rebuild(false);save()});
['category','mode'].forEach(id=>$('#'+id).onchange=()=>{rebuild(false);save()});$('#search').oninput=()=>rebuild(false);$('#ordered').onclick=()=>rebuild();$('#shuffle').onclick=()=>{for(let i=queue.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[queue[i],queue[j]]=[queue[j],queue[i]]}current=queue[0];render();save()};
$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({version:1,...state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='recall-progress-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
$('#import').onchange=async e=>{try{const s=JSON.parse(await e.target.files[0].text());if(s.version!==1||!s.records||!Array.isArray(s.stars))throw Error();const records={};for(const a of DATA){const r=s.records[a.id];if(!r)continue;if(!r.answers||typeof r.answers!=='object')throw Error();const answers={};for(const q of a.questions){const c=r.answers[q.id];if(c!==undefined){if(!q.choices.some(x=>x.id===c))throw Error();answers[q.id]=c}}const submitted=r.submitted===true&&Object.keys(answers).length===a.questions.length;records[a.id]={answers,submitted,correct:submitted?a.questions.filter(q=>answers[q.id]===q.answer).length:0}}state={records:{...state.records,...records},stars:[...new Set([...state.stars,...s.stars.filter(id=>DATA.some(a=>a.id===id))])],current:state.current};save();rebuild();notify('进度已导入')}catch{notify('文件格式不正确，原有进度未更改。')}e.target.value=''};subject=['all','listening','reading','speaking'].includes(state.filters?.subject)?state.filters.subject:'all';updateTasks();if([...$('#category').options].some(o=>o.value===state.filters?.category))$('#category').value=state.filters.category;rebuild();
